mapper.select:
        /* CastSmltMapper.retrieveSmltStng */
        SELECT 
		    SMLT_ID, SMLT_MDL_SN, SMLT_NM, SMLT_TYPE, CRTR_DT, EXCN_YMD, TMNL_ID, SLF_ID, PRNT_ID, 
		    FLT_SCHDL_RSRC_ID, BAG_ALCTN_RSRC_ID, CKNCT_ALCTN_RSRC_ID, PRPT_SET_RSRC_ID, MDL_RSRC_ID, 
		    EXCN_ID, CKNCT_SRVC_HR_RSRC_ID, CHKN_TYPE_RSRC_ID, FCLTY_OPNG_TBL_DG_RSRC_ID, FCLTY_OPNG_TBL_EMI_RSRC_ID, 
		    FCLTY_OPNG_TBL_IMMI_RSRC_ID, FCLTY_OPNG_TBL_SCRTY_CNTRL_RSRC_ID, FCLTY_OPNG_TBL_TR_SCRTY_CNTRL_RSRC_ID, 
		    SBD_CNTRL_ALCTN_ID, PLAN_BGNG_DT, PLAN_END_DT, SMLT_BGNG_DT, SMLT_END_DT, BDPSG_ANCE_YN
		FROM PMOWN.TN_PM_SMLT_STNG
		WHERE 1 = 1

    		AND SMLT_ID = #{smltId} 


	       	AND EXCN_YMD = #{excnYmd}


            AND SMLT_TYPE = #{smltType}

/* CastSmltMapper.retrieveUserSmltCondCnt */
SELECT SUM(A.CNT) AS CNT
FROM (
    SELECT COUNT(*) AS CNT
    FROM PMOWN.TN_PM_SMLT_USER_CHKN_ISL
    WHERE SMLT_ID = #{smltId}
    AND TMNL_ID = #{tmnlId}
    UNION ALL
    SELECT COUNT(*) AS CNT
    FROM PMOWN.TN_PM_SMLT_USER_DEP
    WHERE SMLT_ID = #{smltId}
    AND TMNL_ID = #{tmnlId}
    UNION ALL
    SELECT COUNT(*) AS CNT
    FROM PMOWN.TN_PM_SMLT_USER_FLT_PSG
    WHERE SMLT_ID = #{smltId}
    AND TMNL_ID = #{tmnlId}
) A

/* CastSmltMapper.retrieveNextSmltExcnSn */
-- 시퀀스가 없어 SMLT_ID 스코프의 MAX + 1 로 채번한다.
-- 트랜잭션 격리 수준에 의존하므로 동시 수행 시 PK 충돌로 드러난다 (지시서 5.2 관행 ②)
SELECT NVL(MAX(A.SMLT_EXCN_SN), 0) + 1 AS SMLT_EXCN_SN
FROM PMOWN.TH_PM_SMLT_EXCN_HSTRY A
WHERE A.SMLT_ID = #{smltId}

/* CastSmltMapper.retrieveUserSmltSaveDt */
-- 저장은 3개 탭이 각자 테이블에 넣는다. 화면이 보여주는 것은 "마지막으로 저장한 시각" 하나다
SELECT NVL(TO_CHAR(MAX(A.SAVE_DT), 'YYYYMMDDHH24MISS'), '') AS SAVE_DT
FROM (
    SELECT MAX(NVL(LAST_MDFCN_DT, FRST_REG_DT)) AS SAVE_DT
    FROM PMOWN.TN_PM_SMLT_USER_FLT_PSG
    WHERE SMLT_ID = #{smltId}
    AND TMNL_ID = #{tmnlId}
    UNION ALL
    SELECT MAX(NVL(LAST_MDFCN_DT, FRST_REG_DT)) AS SAVE_DT
    FROM PMOWN.TN_PM_SMLT_USER_CHKN_ISL
    WHERE SMLT_ID = #{smltId}
    AND TMNL_ID = #{tmnlId}
    UNION ALL
    SELECT MAX(NVL(LAST_MDFCN_DT, FRST_REG_DT)) AS SAVE_DT
    FROM PMOWN.TN_PM_SMLT_USER_DEP
    WHERE SMLT_ID = #{smltId}
    AND TMNL_ID = #{tmnlId}
) A
